cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.text();
  // find the path key occurrences (as JSON object keys, with quotes and colon)
  let i = 0, count = 0;
  while (true) {
    const j = txt.indexOf("init-email-login", i);
    if (j < 0) break;
    // only object-key style
    if (txt.slice(j-2, j) === "\"/" || (txt.slice(j-1, j+35).includes("\":"))) {
      count++;
      console.log("=== match at", j, "===");
      console.log(txt.slice(j-3, j + 900));
      console.log("...");
    }
    i = j + 1;
    if (count >= 3) break;
  }
})();
